function resetValue() {
scrubBarSlider.value = currentlyPlayingTime
}
function dispTime(time) {
var min = Math.floor(time / (60 * 1000))
var sec = Math.floor(time % (60 * 1000) / 1000)
if(1 === String(min).length){
min = ("0" + min)
}
sec = ("0" + sec).slice(-2)
return min + ":" + sec
}
onCurrentlyPlayingTimeChanged: {
if (!scrubBarSlider.sliderHoldingPressed) {
scrubBarSlider.value = currentlyPlayingTime
} else {
if (Math.floor(currentlyPlayingTime / 1000) >= Math.floor(totalPlaybackTime / 1000)) {
p.sliderCancel = true
scrubBarSlider.enabled = false
scrubBarSlider.enabled = true
p.sliderCancel = false
scrubBarSlider.value = currentlyPlayingTime
}
}
}
Item {
height: p.sliderAreaHeight
anchors {
top: currentlyPlayingTimeTextArea.bottom
topMargin: scrubBarSlider.sliderHoldingPressed ? p.sliderTopMarginPressed : p.sliderTopMargin
left: parent.left
leftMargin: p.sliderEndPointMargin
right: parent.right
rightMargin: p.sliderEndPointMargin
}
SCmnSlider {
id: scrubBarSlider
anchors.centerIn: parent
sliderStep: (((totalPlaybackTime > 0) && (width > 0)) ? totalPlaybackTime / width : 1)
height: base.barHeight
width: parent.width
value: base.currentlyPlayingTime
maxValue: base.totalPlaybackTime
tapEnable: true
pressAndHoldDuration: 50
expandTapHeightBottom: 30
expandTapWidth: 40
onPressed: {
base.pressed()
}
onReleased: {
if (!p.sliderCancel) {
base.released(scrubBarSlider.value)
}
}
onValueChanged: {
if(base.totalPlaybackTime <= scrubBarSlider.value){
base.playEnded()
}
}
slider_style: SliderStyle {
groove: Item {
Image {
id: grooveImagebg
Image {
id: grooveImagefg
width: styleData.handlePosition
anchors { left: parent.left; verticalCenter: parent.verticalCenter }
fillMode: Image.Stretch
}
Image {
id: grooveImageTopPosition
width: sourceSize.width
height: sourceSize.height
anchors { left: grooveImagefg.right; leftMargin: -1 * Math.round(width / 2); verticalCenter: parent.verticalCenter }
}
}
states: [
State {
name: "not_pressed"
when: !scrubBarSlider.sliderHoldingPressed
PropertyChanges { target: grooveImagebg; source: "qrc:/audio_play_track_seek_first.png" }
PropertyChanges { target: grooveImagefg; source: "qrc:/audio_play_track_seek_complete.png" }
PropertyChanges { target: grooveImageTopPosition; source: "qrc:/btn_audio_play_seekbar_current_point_normal.png" }
},
State {
name: "pressed"
when: scrubBarSlider.sliderHoldingPressed
PropertyChanges { target: grooveImagebg; source: "qrc:/audio_play_track_seek_first_pressed.png" }
PropertyChanges { target: grooveImagefg; source: "qrc:/audio_play_track_seek_complete_pressed.png" }
PropertyChanges { target: grooveImageTopPosition; source: "qrc:/btn_audio_play_seekbar_current_point_pressed.png" }
}
]
}
handle: Item {}
}
onStartedSwipe: base.reqSwipe()
}
}
Item {
id: currentlyPlayingTimeTextArea
width: base.labelTimeWidth
height: p.labelHeight
anchors {
top: base.top; left: base.left;
leftMargin: p.labelTimeHorizontalMargin
}
SCmnMonospaceLabel {
id: currentlyPlayingTimeText
anchors.fill: parent
verticalAlignment: Text.AlignVCenter
horizontalAlignment: Text.AlignHCenter
text: ( scrubBarSlider.value >= 1000*60*1000 ) ? base.totalPlayTimeOver : dispTime(scrubBarSlider.value)
color: base.fontColorTime
font.pixelSize: p.pixelSizeS
font.weight: base.fontWeightTime
}
}
Item {
id: currentlyPlayingTrackNoArea
width: p.labelTrackNoWidth
height: p.labelHeight
anchors { top: base.top; right: slash.left;}
SCmnMonospaceLabel {
id: currentlyPlayingTrackNoText
anchors.fill: parent
verticalAlignment: Text.AlignVCenter
horizontalAlignment: Text.AlignRight
text: ( (10000 <= base.currentryPlayTrackNum) || (base.currentryPlayTrackNum <= 0) ) ? base.totalTrackNumOver : base.currentryPlayTrackNum
color: base.fontColorTrackNo
font.pixelSize: p.pixelSizeS
font.weight: base.fontWeightNo
}
}
Item {
id: slash
width: p.labelSlashWidth
height: p.labelHeight
anchors { top: base.top; horizontalCenter: base.horizontalCenter }
SCmnMonospaceLabel {
anchors.fill: parent
verticalAlignment: Text.AlignVCenter
horizontalAlignment: Text.AlignHCenter
text: "/"
color: base.fontColorTrackNo
font.pixelSize: p.pixelSizeS
font.weight: base.fontWeightNo
}
}
Item {
id: totalPlayingTrackNoArea
width: p.labelTrackNoWidth
height: p.labelHeight
anchors { top: base.top; left: slash.right }
SCmnMonospaceLabel {
id: totalPlayingTrackNoText
anchors.fill: parent
verticalAlignment: Text.AlignVCenter
horizontalAlignment: Text.AlignLeft
text:  ( (10000 <= base.totalPlayTrackNum) || (base.totalPlayTrackNum <= 0) ) ? base.totalTrackNumOver : base.totalPlayTrackNum
color: base.fontColorTrackNo
font.pixelSize: p.pixelSizeS
font.weight: base.fontWeightNo
}
}
Item {
id: totalPlaybackTimeTextArea
width: base.labelTimeWidth
height: p.labelHeight
anchors {
top: base.top; right: base.right;
rightMargin: p.labelTimeHorizontalMargin
}
SCmnMonospaceLabel {
id: totalPlaybackTimeText
anchors.fill: parent
verticalAlignment: Text.AlignVCenter
horizontalAlignment: Text.AlignHCenter
text: ( (base.totalPlaybackTime >= 1000*60*1000) || (base.totalPlaybackTime < 0) ) ? base.totalPlayTimeOver : dispTime(base.totalPlaybackTime)
color: base.fontColorTime
font.pixelSize: p.pixelSizeS
font.weight: base.fontWeightTime
}
}
}
